namespace lf::render {

namespace {
constexpr const char* kLog = "render";
constexpr float kPi = 3.14159265358979f;

Error dxError(const char* what, HRESULT hr) { return Error{"A GPU rendering operation failed.", std::string(what) + ": " + hresultToString(hr), hr}; }

// Mirrors the cbuffer in the shaders (16-byte aligned rows).
struct alignas(16) LayerConstants {
    float transform[16];
    float uvRect[4];
    float csRow0[4];
    float csRow1[4];
    float csRow2[4];
    float adjust0[4];
    float adjust1[4];
    float adjust2[4];
    std::int32_t mode[4];
    float misc[4];
    float fx[4];          // grayscale mix, sepia mix, blur radius (texels), sharpen amount
};
static_assert(sizeof(LayerConstants) % 16 == 0);

// Column-major 4x4 for HLSL mul(matrix, vector) with default (column-major) packing:
// we build row-major here and transpose on upload.
void makeTransform(float out[16], float sx, float sy, float rotationDeg, float tx, float ty) {
    const float r = rotationDeg * kPi / 180.0f;
    const float c = std::cos(r), s = std::sin(r);
    // clip = T * R * S * quad   (row-major)
    const float m[16] = {
        c * sx,  -s * sy, 0, tx,
        s * sx,   c * sy, 0, ty,
        0,        0,      1, 0,
        0,        0,      0, 1,
    };
    // HLSL default packing is column-major; store transposed.
    for (int rI = 0; rI < 4; ++rI)
        for (int cI = 0; cI < 4; ++cI) out[cI * 4 + rI] = m[rI * 4 + cI];
}

void ycbcrMatrix(media::ColorMatrix matrix, bool fullRange, float row0[4], float row1[4], float row2[4]) {
    // Y'CbCr (0..1 texture values) -> R'G'B' (0..1)
    float kr, kb;
    switch (matrix) {
        case media::ColorMatrix::Bt601: kr = 0.299f; kb = 0.114f; break;
        case media::ColorMatrix::Bt2020: kr = 0.2627f; kb = 0.0593f; break;
        default: kr = 0.2126f; kb = 0.0722f; break;
    }
    const float kg = 1.0f - kr - kb;
    const float yScale = fullRange ? 1.0f : 255.0f / 219.0f;
    const float cScale = fullRange ? 1.0f : 255.0f / 224.0f;
    const float yOff = fullRange ? 0.0f : 16.0f / 255.0f;
    const float cOff = 128.0f / 255.0f;
    // R = Y' + 2(1-kr) Cr ; G = Y' - 2 kb(1-kb)/kg Cb - 2 kr(1-kr)/kg Cr ; B = Y' + 2(1-kb) Cb
    const float rCr = 2.0f * (1.0f - kr) * cScale;
    const float gCb = -2.0f * kb * (1.0f - kb) / kg * cScale;
    const float gCr = -2.0f * kr * (1.0f - kr) / kg * cScale;
    const float bCb = 2.0f * (1.0f - kb) * cScale;
    row0[0] = yScale; row0[1] = 0;   row0[2] = rCr; row0[3] = -yScale * yOff - rCr * cOff;
    row1[0] = yScale; row1[1] = gCb; row1[2] = gCr; row1[3] = -yScale * yOff - gCb * cOff - gCr * cOff;
    row2[0] = yScale; row2[1] = bCb; row2[2] = 0;   row2[3] = -yScale * yOff - bCb * cOff;
}
}  // namespace

RenderTarget::~RenderTarget() = default;

Compositor::~Compositor() = default;

Result<std::unique_ptr<Compositor>> Compositor::create(std::shared_ptr<hw::GpuDevice> device) {
    if (!device) return Error{"Compositor needs a GPU device."};
    std::unique_ptr<Compositor> c(new Compositor());
    c->m_device = std::move(device);
    c->m_pool = std::make_shared<FrameTexturePool>(c->m_device);
    if (auto s = c->init(); !s) return s.error();
    LF_LOG_INFO(kLog, "compositor ready on {}", c->m_device->description());
    return c;
}

Status Compositor::init() {
    auto* dev = m_device->device();
    HRESULT hr = dev->CreateVertexShader(g_quad_vs, sizeof g_quad_vs, nullptr, &m_vs);
    if (FAILED(hr)) return dxError("CreateVertexShader", hr);
    hr = dev->CreatePixelShader(g_layer_ps, sizeof g_layer_ps, nullptr, &m_ps);
    if (FAILED(hr)) return dxError("CreatePixelShader", hr);

    D3D11_BUFFER_DESC cb{};
    cb.ByteWidth = sizeof(LayerConstants);
    cb.Usage = D3D11_USAGE_DYNAMIC;
    cb.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
    cb.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
    hr = dev->CreateBuffer(&cb, nullptr, &m_constants);
    if (FAILED(hr)) return dxError("CreateBuffer(constants)", hr);

    D3D11_SAMPLER_DESC sd{};
    sd.Filter = D3D11_FILTER_MIN_MAG_LINEAR_MIP_POINT;
    sd.AddressU = sd.AddressV = sd.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
    sd.MaxLOD = D3D11_FLOAT32_MAX;
    hr = dev->CreateSamplerState(&sd, &m_sampler);
    if (FAILED(hr)) return dxError("CreateSamplerState", hr);

    D3D11_BLEND_DESC bd{};
    bd.RenderTarget[0].BlendEnable = TRUE;
    bd.RenderTarget[0].SrcBlend = D3D11_BLEND_ONE;              // shader outputs premultiplied
    bd.RenderTarget[0].DestBlend = D3D11_BLEND_INV_SRC_ALPHA;
    bd.RenderTarget[0].BlendOp = D3D11_BLEND_OP_ADD;
    bd.RenderTarget[0].SrcBlendAlpha = D3D11_BLEND_ONE;
    bd.RenderTarget[0].DestBlendAlpha = D3D11_BLEND_INV_SRC_ALPHA;
    bd.RenderTarget[0].BlendOpAlpha = D3D11_BLEND_OP_ADD;
    bd.RenderTarget[0].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
    hr = dev->CreateBlendState(&bd, &m_blendPremultiplied);
    if (FAILED(hr)) return dxError("CreateBlendState", hr);
    D3D11_BLEND_DESC od{};
    od.RenderTarget[0].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
    hr = dev->CreateBlendState(&od, &m_blendOpaque);
    if (FAILED(hr)) return dxError("CreateBlendState(opaque)", hr);

    D3D11_RASTERIZER_DESC rd{};
    rd.FillMode = D3D11_FILL_SOLID;
    rd.CullMode = D3D11_CULL_NONE;
    rd.DepthClipEnable = TRUE;
    hr = dev->CreateRasterizerState(&rd, &m_rasterizer);
    if (FAILED(hr)) return dxError("CreateRasterizerState", hr);

    D3D11_DEPTH_STENCIL_DESC dd{};
    dd.DepthEnable = FALSE;
    hr = dev->CreateDepthStencilState(&dd, &m_noDepth);
    if (FAILED(hr)) return dxError("CreateDepthStencilState", hr);
    return Status::success();
}

Result<std::unique_ptr<RenderTarget>> Compositor::createTarget(int width, int height) {
    std::unique_ptr<RenderTarget> t(new RenderTarget());
    t->m_width = std::max(1, width);
    t->m_height = std::max(1, height);
    D3D11_TEXTURE2D_DESC d{};
    d.Width = static_cast<UINT>(t->m_width);
    d.Height = static_cast<UINT>(t->m_height);
    d.MipLevels = 1;
    d.ArraySize = 1;
    d.Format = DXGI_FORMAT_B8G8R8A8_UNORM;
    d.SampleDesc = {1, 0};
    d.Usage = D3D11_USAGE_DEFAULT;
    d.BindFlags = D3D11_BIND_RENDER_TARGET | D3D11_BIND_SHADER_RESOURCE;
    HRESULT hr = m_device->device()->CreateTexture2D(&d, nullptr, &t->m_texture);
    if (FAILED(hr)) return dxError("CreateTexture2D(target)", hr);
    hr = m_device->device()->CreateRenderTargetView(t->m_texture.Get(), nullptr, &t->m_rtv);
    if (FAILED(hr)) return dxError("CreateRenderTargetView", hr);
    hr = m_device->device()->CreateShaderResourceView(t->m_texture.Get(), nullptr, &t->m_srv);
    if (FAILED(hr)) return dxError("CreateShaderResourceView(target)", hr);
    return t;
}

void Compositor::drawTexture(ID3D11ShaderResourceView* srv, const float transform[16], bool premultiplied) {
    auto* ctx = m_device->immediateContext();
    LayerConstants c{};
    std::memcpy(c.transform, transform, sizeof c.transform);
    c.uvRect[0] = 0; c.uvRect[1] = 0; c.uvRect[2] = 1; c.uvRect[3] = 1;
    c.adjust0[0] = 1.0f;
    c.mode[0] = 2;
    c.mode[1] = 16 | (premultiplied ? 8 : 0);
    D3D11_MAPPED_SUBRESOURCE m{};
    if (SUCCEEDED(ctx->Map(m_constants.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &m))) {
        std::memcpy(m.pData, &c, sizeof c);
        ctx->Unmap(m_constants.Get(), 0);
    }
    ID3D11ShaderResourceView* views[3] = {srv, nullptr, nullptr};
    ctx->PSSetShaderResources(0, 3, views);
    ctx->Draw(4, 0);
}

void Compositor::drawLayer(const Layer& layer, int frameW, int frameH, int targetW, int targetH) {
    (void)targetW; (void)targetH;
    const FrameTexture& tex = *layer.texture;
    auto* ctx = m_device->immediateContext();

    // Layer size in frame pixels after fit + user scale + crop.
    const float cropW = std::max(0.0f, 1.0f - layer.crop.left - layer.crop.right);
    const float cropH = std::max(0.0f, 1.0f - layer.crop.top - layer.crop.bottom);
    if (cropW <= 0.0f || cropH <= 0.0f || layer.transform.opacity <= 0.0f) return;
    float base = 1.0f;
    if (layer.fitToFrame) base = std::min(static_cast<float>(frameW) / tex.width(), static_cast<float>(frameH) / tex.height());
    const float scaleX = base * layer.transform.scaleX;
    const float scaleY = base * layer.transform.scaleY;
    const float halfW = tex.width() * cropW * scaleX * 0.5f;
    const float halfH = tex.height() * cropH * scaleY * 0.5f;
    // Crop shifts the visible centre: account for asymmetric crops.
    const float cropCx = (layer.crop.left - layer.crop.right) * 0.5f * tex.width() * scaleX;
    const float cropCy = (layer.crop.top - layer.crop.bottom) * 0.5f * tex.height() * scaleY;

    // Quad corner (cx, cy) in {-1,1}^2, cy = +1 is the image top.
    //   local (frame px, y down) = (cx * halfW, -cy * halfH)
    //   rotated clockwise by theta:  R = [c -s; s c]
    //   translated by (tx, ty)      -> frame pixel position
    //   clip = (x * 2/frameW, -y * 2/frameH)
    const float r = layer.transform.rotation * kPi / 180.0f;
    const float c = std::cos(r), s = std::sin(r);
    const float tx = layer.transform.positionX + cropCx;
    const float ty = layer.transform.positionY + cropCy;
    const float aX = 2.0f / frameW, aY = 2.0f / frameH;
    const float m[16] = {
        aX * c * halfW,   aX * s * halfH,  0, aX * tx,
        -aY * s * halfW,  aY * c * halfH,  0, -aY * ty,
        0, 0, 1, 0,
        0, 0, 0, 1,
    };
    LayerConstants k{};
    for (int rI = 0; rI < 4; ++rI)
        for (int cI = 0; cI < 4; ++cI) k.transform[cI * 4 + rI] = m[rI * 4 + cI];

    k.uvRect[0] = layer.crop.left;
    k.uvRect[1] = layer.crop.top;
    k.uvRect[2] = 1.0f - layer.crop.right;
    k.uvRect[3] = 1.0f - layer.crop.bottom;
    ycbcrMatrix(tex.colorMatrix(), tex.isFullRange(), k.csRow0, k.csRow1, k.csRow2);
    const ColorAdjust& ca = layer.color;
    k.adjust0[0] = layer.transform.opacity; k.adjust0[1] = ca.exposure; k.adjust0[2] = ca.brightness; k.adjust0[3] = ca.contrast;
    k.adjust1[0] = ca.saturation; k.adjust1[1] = ca.temperature; k.adjust1[2] = ca.tint; k.adjust1[3] = ca.highlights;
    k.adjust2[0] = ca.shadows; k.adjust2[1] = ca.gamma; k.adjust2[2] = ca.vibrance; k.adjust2[3] = ca.hue;
    int planeMode = 2;
    switch (tex.kind()) {
        case FrameTexture::Kind::Nv12: planeMode = 0; break;
        case FrameTexture::Kind::I420: planeMode = 1; break;
        case FrameTexture::Kind::Bgra: planeMode = 2; break;
    }
    const EffectParams& fx = layer.effects;
    int flags = 0;
    if (fx.grayscale > 0.0f) flags |= 1;
    if (fx.sepia > 0.0f) flags |= 2;
    if (fx.vignette > 0.0f) flags |= 4;
    if (tex.isPremultiplied()) flags |= 8;
    if (ca.isIdentity() && fx.isIdentity()) flags |= 16;
    if (fx.blur > 0.0f) flags |= 32;
    if (fx.sharpen > 0.0f) flags |= 64;
    k.fx[0] = fx.grayscale;
    k.fx[1] = fx.sepia;
    k.fx[2] = fx.blur;      // in source texels; the shader scales by texel size
    k.fx[3] = fx.sharpen;
    k.mode[0] = planeMode;
    k.mode[1] = flags;
    k.mode[2] = (layer.transform.flipH ? 1 : 0) | (layer.transform.flipV ? 2 : 0);
    k.misc[0] = layer.effects.vignette;
    k.misc[1] = 1.0f / tex.width();
    k.misc[2] = 1.0f / tex.height();
    k.misc[3] = layer.crop.feather;   // source pixels

    D3D11_MAPPED_SUBRESOURCE mapped{};
    if (SUCCEEDED(ctx->Map(m_constants.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped))) {
        std::memcpy(mapped.pData, &k, sizeof k);
        ctx->Unmap(m_constants.Get(), 0);
    }
    ID3D11ShaderResourceView* views[3] = {nullptr, nullptr, nullptr};
    for (int i = 0; i < tex.viewCount() && i < 3; ++i) views[i] = tex.views()[i];
    ctx->PSSetShaderResources(0, 3, views);
    ctx->Draw(4, 0);
}

Status Compositor::compose(RenderTarget& target, int frameWidth, int frameHeight, std::span<const Layer> layers, Rgba background) {
    auto lock = m_device->contextLock();
    auto* ctx = m_device->immediateContext();

    const float bg[4] = {background.r, background.g, background.b, background.a};
    ctx->ClearRenderTargetView(target.rtv(), bg);

    D3D11_VIEWPORT vp{0, 0, static_cast<float>(target.width()), static_cast<float>(target.height()), 0, 1};
    ctx->RSSetViewports(1, &vp);
    ctx->RSSetState(m_rasterizer.Get());
    ID3D11RenderTargetView* rtvs[] = {target.rtv()};
    ctx->OMSetRenderTargets(1, rtvs, nullptr);
    ctx->OMSetDepthStencilState(m_noDepth.Get(), 0);
    const float blendFactor[4] = {0, 0, 0, 0};
    ctx->OMSetBlendState(m_blendPremultiplied.Get(), blendFactor, 0xFFFFFFFF);
    ctx->IASetInputLayout(nullptr);
    ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLESTRIP);
    ctx->VSSetShader(m_vs.Get(), nullptr, 0);
    ctx->PSSetShader(m_ps.Get(), nullptr, 0);
    ID3D11Buffer* cbs[] = {m_constants.Get()};
    ctx->VSSetConstantBuffers(0, 1, cbs);
    ctx->PSSetConstantBuffers(0, 1, cbs);
    ID3D11SamplerState* samplers[] = {m_sampler.Get()};
    ctx->PSSetSamplers(0, 1, samplers);

    for (const Layer& layer : layers) {
        if (!layer.texture) continue;
        drawLayer(layer, frameWidth, frameHeight, target.width(), target.height());
    }
    ID3D11ShaderResourceView* nulls[3] = {nullptr, nullptr, nullptr};
    ctx->PSSetShaderResources(0, 3, nulls);
    ID3D11RenderTargetView* none[] = {nullptr};
    ctx->OMSetRenderTargets(1, none, nullptr);
    return Status::success();
}

Status Compositor::blit(RenderTarget& source, ID3D11RenderTargetView* backBuffer, int bbW, int bbH, IntRect dst, Rgba surround) {
    auto lock = m_device->contextLock();
    auto* ctx = m_device->immediateContext();
    const float bg[4] = {surround.r, surround.g, surround.b, surround.a};
    ctx->ClearRenderTargetView(backBuffer, bg);
    if (dst.width <= 0 || dst.height <= 0) return Status::success();

    D3D11_VIEWPORT vp{0, 0, static_cast<float>(bbW), static_cast<float>(bbH), 0, 1};
    ctx->RSSetViewports(1, &vp);
    ctx->RSSetState(m_rasterizer.Get());
    ID3D11RenderTargetView* rtvs[] = {backBuffer};
    ctx->OMSetRenderTargets(1, rtvs, nullptr);
    ctx->OMSetDepthStencilState(m_noDepth.Get(), 0);
    ctx->OMSetBlendState(m_blendOpaque.Get(), nullptr, 0xFFFFFFFF);
    ctx->IASetInputLayout(nullptr);
    ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLESTRIP);
    ctx->VSSetShader(m_vs.Get(), nullptr, 0);
    ctx->PSSetShader(m_ps.Get(), nullptr, 0);
    ID3D11Buffer* cbs[] = {m_constants.Get()};
    ctx->VSSetConstantBuffers(0, 1, cbs);
    ctx->PSSetConstantBuffers(0, 1, cbs);
    ID3D11SamplerState* samplers[] = {m_sampler.Get()};
    ctx->PSSetSamplers(0, 1, samplers);

    // dst rect (pixels, y down) -> clip space
    const float sx = dst.width / static_cast<float>(bbW);
    const float sy = dst.height / static_cast<float>(bbH);
    const float tx = (dst.x + dst.width * 0.5f) / bbW * 2.0f - 1.0f;
    const float ty = 1.0f - (dst.y + dst.height * 0.5f) / bbH * 2.0f;
    float t[16];
    makeTransform(t, sx, sy, 0.0f, tx, ty);
    drawTexture(source.srv(), t, true);

    ID3D11ShaderResourceView* nulls[3] = {nullptr, nullptr, nullptr};
    ctx->PSSetShaderResources(0, 3, nulls);
    return Status::success();
}

Status Compositor::readback(RenderTarget& target, std::vector<std::uint8_t>& out) {
    auto lock = m_device->contextLock();
    auto* ctx = m_device->immediateContext();
    if (!target.m_staging) {
        D3D11_TEXTURE2D_DESC d{};
        target.m_texture->GetDesc(&d);
        d.Usage = D3D11_USAGE_STAGING;
        d.BindFlags = 0;
        d.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
        d.MiscFlags = 0;
        HRESULT hr = m_device->device()->CreateTexture2D(&d, nullptr, &target.m_staging);
        if (FAILED(hr)) return dxError("CreateTexture2D(staging)", hr);
    }
    ctx->CopyResource(target.m_staging.Get(), target.m_texture.Get());
    D3D11_MAPPED_SUBRESOURCE m{};
    HRESULT hr = ctx->Map(target.m_staging.Get(), 0, D3D11_MAP_READ, 0, &m);
    if (FAILED(hr)) return dxError("Map(staging)", hr);
    const std::size_t rowBytes = static_cast<std::size_t>(target.width()) * 4;
    out.resize(rowBytes * target.height());
    for (int y = 0; y < target.height(); ++y) {
        std::memcpy(out.data() + y * rowBytes, static_cast<const std::uint8_t*>(m.pData) + static_cast<std::size_t>(y) * m.RowPitch, rowBytes);
    }
    ctx->Unmap(target.m_staging.Get(), 0);
    return Status::success();
}

}  // namespace lf::render
